def test_bit_fields_do_not_bleed():
    """单独翻转每个字段的位，不影响其他字段。"""
    packed0 = gbuffer.pack_pixel((0.0, 0.0, 1.0), 0.5, 3)
    base = gbuffer.unpack_pixel(packed0)

    fields = [
        (gbuffer.ROUGH_SHIFT, gbuffer.ROUGH_BITS),
        (gbuffer.MATERIAL_SHIFT, gbuffer.MATERIAL_BITS),
        (gbuffer.AZIMUTH_SHIFT, gbuffer.AZIMUTH_BITS),
        (gbuffer.POLAR_SHIFT, gbuffer.POLAR_BITS),
    ]
    for shift, width in fields:
        flipped = gbuffer.unpack_pixel(packed0 ^ (1 << (shift + width - 1)))
        for key in ("normal", "rough", "mat"):
            same = flipped[key] == base[key]
            if (shift, width) == (gbuffer.MATERIAL_SHIFT, gbuffer.MATERIAL_BITS):
                assert key == "mat" or same
            elif (shift, width) == (gbuffer.ROUGH_SHIFT, gbuffer.ROUGH_BITS):
                assert key != "rough" or same
            else:
                assert key != "normal" or same

